import {REQUIRED,find,header} from './engine.js';
const NS='http://schemas.openxmlformats.org/spreadsheetml/2006/main';
const esc=s=>String(s??'').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');
function xml(text){if(/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('지원하지 않는 XML 형식입니다.');const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error('엑셀 파일 내부 형식이 손상되었습니다.');return doc;}
const nodes=(el,name)=>[...el.getElementsByTagNameNS('*',name)];
const richText=el=>nodes(el,'t').filter(t=>t.parentNode.localName!=='rPh').map(t=>t.textContent).join('');
function column(ref){let n=0;for(const c of ref||''){if(c<'A'||c>'Z')break;n=n*26+c.charCodeAt(0)-64;}return n-1;}
function zipLimits(buffer){const v=new DataView(buffer);let end=-1;for(let i=v.byteLength-22;i>=Math.max(0,v.byteLength-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('올바른 .xlsx 파일이 아닙니다.');const entries=v.getUint16(end+10,true);let at=v.getUint32(end+16,true),total=0;if(entries===65535||at===0xffffffff)throw Error('파일이 너무 큽니다. 기간을 나눠 주세요.');for(let n=0;n<entries;n++){if(at+46>v.byteLength||v.getUint32(at,true)!==0x02014b50)throw Error('엑셀 압축 구조가 손상되었습니다.');const size=v.getUint32(at+24,true);total+=size;if(size>300*1024*1024||total>700*1024*1024)throw Error('엑셀 데이터가 너무 큽니다. 다운로드 기간을 나눠 주세요.');at+=46+v.getUint16(at+28,true)+v.getUint16(at+30,true)+v.getUint16(at+32,true);}}
export async function readXlsx(file,onProgress=()=>{}){
 if(!/\.xlsx$/i.test(file.name))throw Error('.xlsx 파일을 선택해 주세요.');if(file.size>200*1024*1024)throw Error('200MB 이하 파일을 선택해 주세요.');onProgress('엑셀 파일을 읽는 중…');
 const buffer=await file.arrayBuffer();zipLimits(buffer);const zip=await globalThis.JSZip.loadAsync(buffer);
 async function read(path){const f=zip.file(path);if(!f)throw Error('엑셀 파일에 필요한 구성요소가 없습니다.');return xml(await f.async('string'));}
 const strings=zip.file('xl/sharedStrings.xml')?nodes(await read('xl/sharedStrings.xml'),'si').map(richText):[];
 const rels=new Map(nodes(await read('xl/_rels/workbook.xml.rels'),'Relationship').filter(r=>r.getAttribute('TargetMode')!=='External').map(r=>[r.getAttribute('Id'),r.getAttribute('Target')]));
 for(const sheet of nodes(await read('xl/workbook.xml'),'sheet')){
  const rid=sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id'),target=rels.get(rid);if(!target)continue;
  const url=new URL(target.replace(/\\/g,'/'),'https://xlsx.local/xl/workbook.xml');if(url.origin!=='https://xlsx.local')continue;const path=decodeURIComponent(url.pathname.slice(1));if(!path.includes('worksheets/'))continue;
  const doc=await read(path),metadata={},rows=[];let headers=null,fallback=0;
  for(const row of nodes(doc,'row')){fallback++;const cells=[];let next=0;for(const c of nodes(row,'c')){let col=column(c.getAttribute('r'));if(col<0)col=next;next=col+1;if(col>200)continue;const kind=c.getAttribute('t');let val=nodes(c,'v')[0]?.textContent||'';if(kind==='s')val=strings[Number(val)]||'';else if(kind==='inlineStr')val=richText(c);else if(kind==='e')val='';cells[col]=val;}
   if(!cells.some(v=>String(v??'').trim()))continue;
   if(!headers){if(!cells.some(v=>header(v)==='단지명')){for(const v of cells){const m=String(v??'').match(/^(계약일자|실거래 구분|주소구분|시도|시군구|읍면동|단지명|면적|금액선택)\s*:\s*(.*)$/);if(m)metadata[m[1]]=m[2].trim();}continue;}
    const missing=REQUIRED.filter(k=>find(cells,k)<0);if(missing.length)throw Error('아파트·오피스텔 매매 자료만 지원합니다. 필수 열: '+missing.join(', '));headers=Array.from(cells,v=>v??'');
   }else{if(find(cells,'단지명')>=0&&find(cells,'거래금액')>=0)continue;rows.push({rowNumber:Number(row.getAttribute('r'))||fallback,cells:Array.from({length:headers.length},(_,i)=>cells[i]??'')});if(rows.length>250000)throw Error('거래가 25만 건을 넘습니다. 기간을 나눠 주세요.');}
   if(fallback%2000===0){onProgress(`${rows.length.toLocaleString()}건 읽는 중…`);await new Promise(r=>setTimeout(r,0));}
  }
  if(headers){if(!rows.length)throw Error('거래 내역이 없습니다.');return {name:file.name,sheetName:sheet.getAttribute('name'),headers,metadata,rows};}
 }
 throw Error('실거래가 표를 찾지 못했습니다. 국토부 매매 원본 파일을 선택해 주세요.');
}
const colName=n=>{let s='';for(n++;n>0;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s;};
function worksheet(headers,rows){const data=[headers,...rows].map((row,i)=>'<row r="'+(i+1)+'">'+row.map((v,j)=>{if(v==null)return '';const r=colName(j)+(i+1);return typeof v==='number'&&Number.isFinite(v)?`<c r="${r}" s="2"><v>${v}</v></c>`:`<c r="${r}" t="inlineStr" s="${i===0?1:0}"><is><t xml:space="preserve">${esc(v)}</t></is></c>`;}).join('')+'</row>').join('');return `<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="${NS}"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>${headers.map((h,i)=>`<col min="${i+1}" max="${i+1}" width="${h.includes('주소')?42:h.includes('단지')?30:22}" customWidth="1"/>`).join('')}</cols><sheetData>${data}</sheetData><autoFilter ref="A1:${colName(headers.length-1)}${rows.length+1}"/></worksheet>`;}
export async function exportXlsx(source,all,columns){const zip=new globalThis.JSZip();const sheets=[{name:'원본',headers:[...source.headers,'분석 판정'],rows:all.raw.map(t=>[...t.cells,t.reason])},{name:'단지별 평당가',headers:columns.apartments.map(c=>c.exportLabel||c.label),rows:all.apartments.map(t=>columns.apartments.map(c=>c.value(t)))},{name:'동·단지별 평당가',headers:columns.districts.map(c=>c.exportLabel||c.label),rows:all.districts.map(t=>columns.districts.map(c=>c.value(t)))}];
 const rel='http://schemas.openxmlformats.org/officeDocument/2006/relationships';
 zip.file('[Content_Types].xml',`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`);
 zip.file('_rels/.rels',`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="${rel}/officeDocument" Target="xl/workbook.xml"/></Relationships>`);
 zip.file('xl/workbook.xml',`<workbook xmlns="${NS}" xmlns:r="${rel}"><sheets>${sheets.map((s,i)=>`<sheet name="${s.name}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`);
 zip.file('xl/_rels/workbook.xml.rels',`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="${rel}/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId4" Type="${rel}/styles" Target="styles.xml"/></Relationships>`);
 zip.file('xl/styles.xml',`<styleSheet xmlns="${NS}"><fonts count="2"><font><sz val="11"/><name val="맑은 고딕"/></font><font><sz val="11"/><name val="맑은 고딕"/><b/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0"/><xf numFmtId="3" fontId="0" fillId="0" borderId="0" xfId="0"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`);
 sheets.forEach((s,i)=>zip.file(`xl/worksheets/sheet${i+1}.xml`,worksheet(s.headers,s.rows)));return zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',compression:'DEFLATE'});
}
